              AND ACCOUNT_PERIOD <= CONCAT(YEAR(v_data_date), 'Q', QUARTER(v_data_date))
        ) up_streak
        WHERE break_cnt = 0
    ), 0) + COALESCE((
        SELECT COUNT(*)
